def test_connect_picks_the_kind_from_the_url() -> None:
    backend = Backend.connect("memory:", id="from-url")
    assert isinstance(backend, MemoryBackend)
    assert backend.id == "from-url"
    with pytest.raises(ConfigurationError):
        Backend.connect("https://caldav.example.com/")
    with pytest.raises(ConfigurationError):
        Backend.connect("memory:", kind="no-such-kind")


def test_verify_catches_a_silent_drop() -> None:
    backend = MemoryBackend(silently_drop=["CATEGORIES"])
    collection = backend.collection("default")
    task = Task.new(summary="x", categories=["work"])
    collection.add(task)  # not verified: nobody notices
    with pytest.raises(VerificationError) as info:
        collection.add(Task.new(summary="y", categories=["work"]), verify=True)
    assert [d.property for d in info.value.differences] == ["CATEGORIES"]
    assert info.value.backend == "memory"


