def test_bind_replaces_the_collection() -> None:
    backend = MemoryBackend()
    first = backend.collection("default")
    second = backend.create_collection("second")
    stored = first.add_task(summary="x")
    rebound = second.bind(stored)
    assert rebound.collections == (second,)
    assert rebound.native is None
    assert stored.collection is first


