def test_fan_out_returns_partial_results() -> None:
    good = MemoryBackend(id="good")
    (good.collection("default")).add_task(summary="found")
    with Workspace([good, Unreachable(id="down")]) as workspace:
        listed = workspace.collections()
        assert [c.id for c in listed.items] == ["default"]
        assert set(listed.errors) == {"down"}
        found = workspace.search(todo=True)
        assert [str(i.component["SUMMARY"]) for i in found.items] == ["found"]
        assert set(found.errors) == {"down"}
        with pytest.raises(ExceptionGroup):
            found.raise_for_errors()
        assert (workspace.collection("default")).backend_id == "good"
        with pytest.raises(NotFoundError):
            workspace.collection("nope")
    MultiResult().raise_for_errors()


