def test_completed_is_utc() -> None:
    collection = MemoryBackend().collection("default")
    task = collection.add_task(summary="x")
    oslo = timezone(timedelta(hours=2))
    task.complete(at=datetime(2026, 11, 1, 14, tzinfo=oslo))
    assert b"COMPLETED:20261101T120000Z" in task.to_ical()


